{
	int index = e->getIndex(owner);
	Edge* lastEdge = edges.last();
	Primitive* lastNeighbor = neighbors.last();
	edges[index] = lastEdge;
	neighbors[index] = lastNeighbor;
	edges.popDiscard();
	neighbors.popDiscard();
	lastEdge->setIndex(owner, index);
	e->setIndex(owner, -1);
}

